ok(await page.evaluate(() => document.activeElement.id) === 'registered-heading', 'focus to table heading after drop');
await page.fill('#email', 'bad'); await page.fill('#phone', 'abc'); await page.click('#contact-form button[type=submit]');
ok(await page.locator('#error-summary li').count() === 2, 'profile 2 errors'); await axe('profile errors');
await page.fill('#email', 'j@n.edu'); await page.fill('#phone', ''); await page.fill('#name', 'Sam Lee'); await page.click('#contact-form button[type=submit]');
ok((await page.textContent('#avatar')) === 'SL' && await page.locator('#profile-saved').isVisible(), 'profile saved');
