await m.click('.nav-toggle');
ok(await m.evaluate(() => document.documentElement.scrollWidth <= 375), 'no horizontal overflow on mobile catalog');
await m.screenshot({ path: 'shots/mobile-catalog.png', fullPage: true });
await m.goto(BASE + 'profile.html'); await m.screenshot({ path: 'shots/mobile-profile.png', fullPage: true });
ok(await m.evaluate(() => document.documentElement.scrollWidth <= 375), 'no page overflow on mobile profile (table scrolls in region)');
ok(errs.length === 0, 'no JS errors ' + errs.join('; '));
