cd /tmp/e2e && export LD_LIBRARY_PATH=$(cat /tmp/libs/path) FONTCONFIG_FILE=/tmp/libs/fc/fonts.conf; cat > ov.mjs <<'EOF'
import fs from 'fs'; import path from 'path';
import { chromium } from 'playwright';
const b = await chromium.launch(); const c = await b.newContext({ viewport: { width: 375, height: 800 } });
await c.route('http://app.test/**', r => { const f = path.join('/work', new URL(r.request().url()).pathname); r.fulfill({ status: 200, contentType: f.endsWith('.js') ? 'text/javascript' : f.endsWith('.css') ? 'text/css' : 'text/html', body: fs.readFileSync(f) }); });
const p = await c.newPage();
for (const pg of ['index.html','register.html','profile.html']) {
await p.goto('http://app.test/' + pg);
console.log(pg, await p.evaluate(() => [document.documentElement.scrollWidth, ...[...document.querySelectorAll('body *')].filter(e => e.getBoundingClientRect().right > 376 && !e.closest('.table-wrap')).slice(0,5).map(e => e.tagName + '.' + e.className + '#' + e.id + ' ' + Math.round(e.getBoundingClientRect().right))]));
}
await b.close();
EOF
node ov.mjs 2>&1 | grep -v Fontconfig

